import{_ as t,o as a,c as o,ae as n}from"./chunks/framework.sgRordCm.js";const m=JSON.parse('{"title":"The use of AI","description":"","frontmatter":{},"headers":[],"relativePath":"features/ai.md","filePath":"features/ai.md"}'),i={name:"features/ai.md"};function s(d,e,h,r,u,l){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="the-use-of-ai" tabindex="-1">The use of AI <a class="header-anchor" href="#the-use-of-ai" aria-label="Permalink to &quot;The use of AI&quot;">​</a></h1><p>You want to know what a tool sends to a language model before you give it your code.</p><h2 id="what-heidrun-does" tabindex="-1">What Heidrun does <a class="header-anchor" href="#what-heidrun-does" aria-label="Permalink to &quot;What Heidrun does&quot;">​</a></h2><p>Heidrun has no language model and no server of its own. When a feature needs a language model, Heidrun asks the coding agent that is already installed on your computer: <code>codex</code> when it is installed, <code>claude</code> otherwise. The request goes to the provider of that coding agent, with your own account, like any prompt that you type yourself. When no coding agent is installed, Heidrun makes no call.</p><h2 id="where-heidrun-uses-a-language-model" tabindex="-1">Where Heidrun uses a language model <a class="header-anchor" href="#where-heidrun-uses-a-language-model" aria-label="Permalink to &quot;Where Heidrun uses a language model&quot;">​</a></h2><p>Four features use a language model:</p><table tabindex="0"><thead><tr><th>Feature</th><th>When Heidrun makes a call</th><th>What Heidrun sends</th><th>Default</th></tr></thead><tbody><tr><td>Dynamic topics, method &quot;Language model&quot;, in the Past chats sidebar section</td><td>When a chat of the list has no dynamic topic, or has new messages</td><td>The title of each chat, and the first messages that you typed. Never the messages of the coding agent, the files, the issues, or the pull requests</td><td>Off: the method &quot;Keyword&quot; is the default</td></tr><tr><td>Clustered dynamic topics, in the Past chats sidebar section</td><td>When a new dynamic topic appears</td><td>Only the short labels of the dynamic topics. Never the text of a chat</td><td>Off</td></tr><tr><td>The commit message, in the Source control sidebar section</td><td>Only when you click the sparkle button &quot;Write the commit message with a coding agent&quot;</td><td>The diff of the staged files, or of every change when no file is staged</td><td>Only on a click</td></tr><tr><td>The name and the description of a custom launcher, in the Launchers sidebar section</td><td>Only when you click the button &quot;Write the empty fields (name, description) with a coding agent&quot;</td><td>What you wrote in the window: the command line, or the prompt of the coding agent</td><td>Only on a click</td></tr></tbody></table><h2 id="what-stays-on-your-computer" tabindex="-1">What stays on your computer <a class="header-anchor" href="#what-stays-on-your-computer" aria-label="Permalink to &quot;What stays on your computer&quot;">​</a></h2><ul><li>The method &quot;Keyword&quot; of the dynamic topics finds the dynamic topics on your computer, with no language model. It reads the titles of the issues and of the pull requests on GitHub or GitLab, with the command <code>gh</code> or <code>glab</code>.</li><li>The summary of each chat, its tokens, and its estimated cost come from the files of the chat, with no language model. Heidrun downloads the public price list of the project LiteLLM once a day, and sends nothing with the download.</li><li>The Statistics window counts facts with fixed rules, and never uses a language model.</li></ul><h2 id="how-to-switch-it-off" tabindex="-1">How to switch it off <a class="header-anchor" href="#how-to-switch-it-off" aria-label="Permalink to &quot;How to switch it off&quot;">​</a></h2><p>In the section &quot;Dynamic topics&quot; of the Settings window:</p><ul><li>Keep the method &quot;Keyword&quot;, or switch off &quot;Enable dynamic topics&quot;.</li><li>Keep &quot;Enable clustered dynamic topics&quot; off.</li></ul><p>The commit message and the custom launcher use a language model only when you click their button.</p><p><em>Heidrun asks your own einherjar for help, and never a stranger from outside Valhalla.</em></p>',14)])])}const f=t(i,[["render",s]]);export{m as __pageData,f as default};
